try {
  final item = await repository.load(id);
  if (item.active && item.owner != null && item.owner!.enabled) results.add(item);
} catch (e) {
  // Log and continue to avoid losing all items due to a single failure
  continue;
}

def test_enrich_filters_items_correctly() async {
  final repo = _MockRepository();
  final ids = ['a', 'b', 'c'];

  // Setup mocks for different item states
  when(repo.load('a')).thenAnswer((_) async => Item(active: true, owner: User(enabled: true)));
  when(repo.load('b')).thenAnswer((_) async => Item(active: false, owner: User(enabled: true)));
  when(repo.load('c')).thenAnswer((_) async => Item(active: true, owner: null));

  final result = await enrich(ids, repo);
  expect(result, hasLength(1));
  expect(result.first.id, 'a');
}

