  continue;
}
results.add(item);

@Test
void enrich_onlyIncludesItemsWithEnabledOwner() {
  var owner = new Owner(true);
  var repo = mock(Repository.class);
  when(repo.load(1L)).thenReturn(new Item(1L, true, owner));
  when(repo.load(2L)).thenReturn(new Item(2L, true, new Owner(false)));
  assertThat(enrich(asList(1L, 2L), repo)).containsExactly(new Item(1L, true, owner));
}

